const $=s=>document.querySelector(s),money=n=>'₹'+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const configs=[{name:'EMI & repayments',intro:'Home, car, personal or education loans.',fields:[['p','Loan amount (₹)',500000],['r','Annual interest (%)',10],['n','Term (months)',60],['x','Extra monthly payment (₹)',0]]},{name:'Compare loans',intro:'Compare the same amount with different rates, terms and upfront fees.',fields:[['p','Loan amount (₹)',500000],['a','Loan A rate (%)',10],['b','Loan B rate (%)',9],['na','Loan A months',60],['nb','Loan B months',60],['fa','Loan A fee (₹)',0],['fb','Loan B fee (₹)',5000]]},{name:'Flat / interest only',intro:'Interest calculated on the original principal throughout the term.',fields:[['p','Principal (₹)',100000],['r','Annual interest (%)',12],['n','Term (months)',12]]},{name:'Chit fund',intro:'Estimate one auction, with commission included in the discount.',fields:[['p','Chit face value (₹)',100000],['n','Members / installments',20],['d','Auction discount (%)',25],['c','Organizer commission (%)',5]]}];
let mode=0,schedule=[],lastResult={};
function payment(p,r,n){let rate=r/1200;return rate?p*rate/-Math.expm1(-n*Math.log1p(rate)):p/n}
function amort(p,r,n,x=0){let e=payment(p,r,n),bal=p,rows=[];for(let i=1;i<=n;i++){let interest=bal*r/1200,paid=Math.min(e+x,bal+interest);if(i===n)paid=bal+interest;let principal=paid-interest;bal=Math.max(0,bal-principal);rows.push([i,paid,principal,interest,bal]);if(bal<1e-8)break}return rows}
function read(){let v={};for(let [key,label] of configs[mode].fields){let el=$('#f-'+key),raw=el.value.trim(),n=Number(raw);if(!raw||!Number.isFinite(n)||n<0||n>1e12)throw Error(label+': enter a valid nonnegative number (up to 1 trillion).');if(['p','n','na','nb'].includes(key)&&n<=0)throw Error(label+' must be greater than zero.');if(['n','na','nb'].includes(key)&&(!Number.isInteger(n)||n>1200))throw Error(label+': use a whole number from 1 to 1200.');v[key]=n}if(mode===3&&!(v.c<=v.d&&v.d<=100))throw Error('Use commission ≤ discount ≤ 100%.');return v}
function calculate(){try{const v=read();let hero,label,metrics,note='',ratio=null;schedule=[];if(mode===0){schedule=amort(v.p,v.r,v.n,v.x);let interest=schedule.reduce((s,r)=>s+r[3],0),baseline=amort(v.p,v.r,v.n).reduce((s,r)=>s+r[3],0);hero=money(payment(v.p,v.r,v.n));label='YOUR MONTHLY EMI';metrics=[['Total interest',money(interest)],['Total repayment',money(v.p+interest)],['Paid off in',schedule.length+' months'],['Interest saved',money(Math.max(0,baseline-interest))]];ratio=v.p/(v.p+interest)*100;note=v.x?'Includes '+money(v.x)+' extra each month. Final payment is adjusted.':'Fixed monthly payments. Final payment is adjusted to clear the balance.'}else if(mode===1){let a=payment(v.p,v.a,v.na),b=payment(v.p,v.b,v.nb),ta=a*v.na+v.fa,tb=b*v.nb+v.fb;hero=money(Math.abs(ta-tb));label='DIFFERENCE IN TOTAL COST';metrics=[['Loan A EMI',money(a)],['Loan B EMI',money(b)],['Loan A total + fee',money(ta)],['Loan B total + fee',money(tb)]];note=Math.abs(ta-tb)<.005?'Both loans have the same total cash outflow.':'Loan '+(ta<tb?'A':'B')+' has the lower total cash outflow. Fees are paid upfront.'}else if(mode===2){let i=v.p*v.r/100*v.n/12;hero=money((v.p+i)/v.n);label='FLAT-LOAN MONTHLY PAYMENT';metrics=[['Total interest',money(i)],['Total repayment',money(v.p+i)],['Interest-only monthly',money(i/v.n)],['Interest-only final payment',money(v.p+i/v.n)]];note='For interest-only loans, repay the principal with the final interest payment.'}else{let cut=v.p*v.d/100,fee=v.p*v.c/100,div=(cut-fee)/v.n;hero=money(v.p-cut);label='WINNER PAYOUT';metrics=[['Gross installment',money(v.p/v.n)],['Dividend per member',money(div)],['Net installment',money(v.p/v.n-div)],['Organizer commission',money(fee)]];note='Dividend pool: '+money(cut-fee)+'. This is one auction, not a full-cycle return.'}$('#error').textContent='';$('#hero').textContent=hero;$('#result-label').textContent=label;$('#metrics').innerHTML=metrics.map(([l,x])=>'<div class="metric"><span>'+l+'</span><strong>'+x+'</strong></div>').join('');$('#result-note').textContent=note;$('#chart').innerHTML=ratio===null?'':'<div class="bar"><span style="width:'+ratio+'%"></span></div><div class="legend"><span>Principal '+ratio.toFixed(1)+'%</span><span>Interest '+(100-ratio).toFixed(1)+'%</span></div>';$('#schedule').hidden=mode!==0;$('#rows').innerHTML=schedule.map(row=>'<tr>'+row.map((v,i)=>'<td>'+(i?money(v):v)+'</td>').join('')+'</tr>').join('');lastResult={calculator:configs[mode].name,label,value:hero,metrics,note};return lastResult}catch(e){$('#error').textContent=e.message;$('#hero').textContent='—';$('#metrics').innerHTML='';$('#chart').innerHTML='';$('#result-note').textContent='Correct the highlighted inputs and calculate again.';$('#schedule').hidden=true;lastResult={error:e.message};return lastResult}}
function select(i){mode=i;$('#tabs').innerHTML=configs.map((c,j)=>'<button type="button" aria-pressed="'+(i===j)+'" class="'+(i===j?'active':'')+'" data-mode="'+j+'">'+c.name+'</button>').join('');$('#title').textContent=configs[i].name;$('#number').textContent='0'+(i+1);$('#intro').textContent=configs[i].intro;$('#fields').innerHTML=configs[i].fields.map(([k,l,v])=>'<label for="f-'+k+'">'+l+'<input id="f-'+k+'" name="'+k+'" type="number" min="0" step="any" required value="'+v+'"></label>').join('');calculate()}
$('#tabs').onclick=e=>{const b=e.target.closest('[data-mode]');if(b)select(Number(b.dataset.mode))};$('#form').onsubmit=e=>{e.preventDefault();calculate()};$('#form').addEventListener('input',()=>calculate());$('#export').onclick=()=>{if(!schedule.length)return;let csv='Month,Payment,Principal,Interest,Balance\n'+schedule.map(r=>r.map((v,i)=>i?v.toFixed(2):v).join(',')).join('\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='repayment-schedule.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};select(0);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_calculator_result',description:'Read the currently displayed money calculator result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object.');return lastResult}})).catch(()=>{})}catch(e){}}
